import { getPool } from "./_db.js";
import { ensureDebugTable, DEBUG_TOKEN_RE, DEBUG_TTL_HOURS } from "./_debug-hits.js";
/**
 * GET /api/analytics-debug?token=<debug token>&after=<last seen id>
 *
 * Public, no-auth endpoint for the /analytics/debug page. Returns the hits
 * /api/a recorded for one debug session (see api/_debug-hits.js), oldest
 * first, newer than `after` so the page can poll incrementally. The token
 * itself is the access control: it's random, generated by the debugger page,
 * and only ever attached to hits by a browser that opened ?ia_debug=<token>.
 */
const PAGE_SIZE = 200;

export default async function handler(req, res) {
    res.setHeader("Cache-Control", "no-store");
    res.setHeader("Access-Control-Allow-Origin", "*");
    res.setHeader("Access-Control-Allow-Methods", "GET, OPTIONS");

    if (req.method === "OPTIONS") return res.status(204).end();
    if (req.method !== "GET") {
        res.setHeader("Allow", "GET");
        return res.status(405).json({ error: "Method not allowed" });
    }

    const token = String(req.query.token || "");
    if (!DEBUG_TOKEN_RE.test(token)) {
        return res.status(400).json({ error: "Invalid debug token" });
    }
    const after = Math.max(0, parseInt(req.query.after || "0", 10) || 0);

    const db = getPool();
    try {
        await ensureDebugTable(db);

        // Opportunistic retention sweep — cheap thanks to the received_at
        // index, and the debugger page is the only consumer of this table.
        if (Math.random() < 0.05) {
            await db.query(
                `DELETE FROM analytics_debug_hits WHERE received_at < NOW() - make_interval(hours => $1)`,
                [DEBUG_TTL_HOURS]
            ).catch(() => {});
        }

        const { rows } = await db.query(
            `SELECT id, received_at, site_id, hit_type, event_name, status, verdict, reason, payload
             FROM analytics_debug_hits
             WHERE token = $1 AND id > $2 AND received_at > NOW() - make_interval(hours => $3)
             ORDER BY id ASC
             LIMIT $4`,
            [token, after, DEBUG_TTL_HOURS, PAGE_SIZE]
        );
        return res.status(200).json({ hits: rows });
    } catch (err) {
        console.error("[analytics-debug]", err);
        return res.status(500).json({ error: "Failed to load debug hits" });
    }
}
